import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="10d",progress=False,auto_adjust=True); close=data["Close"]; print("\n".join(f"{t}: {float(close[t].iloc[-1]):.2f} | Variation 5j: {((float(close[t].iloc[-1])/float(close[t].iloc[-6])-1)*100):+.2f}%" for t in tickers if t in close.columns))
